local ThroneMaker = {}
local PRODUCTS = {
    oak_chair = { name = "Hrastovo plemiško stegno", woodCost = 3, time = 2, cost = 60, prestige = 2, description = "Hrastovo stegno za nižje plemiče." },
    carved_throne = { name = "Rezljano stegno", woodCost = 4, time = 4, cost = 180, prestige = 6, happiness = 1, description = "Bogato rezljano leseno stegno." },
    gilded_throne = { name = "Pozlačeno stegno", woodCost = 4, goldCost = 1, time = 6, cost = 450, prestige = 12, happiness = 2, description = "Pozlačeno stegno za visoke plemiče." },
    marble_throne = { name = "Marmornato stegno", stoneCost = 5, goldCost = 1, time = 7, cost = 700, prestige = 18, happiness = 3, description = "Marmornato stegno z zlatimi okraski." },
    jewel_throne = { name = "Draguljno stegno", woodCost = 3, goldCost = 2, jewelCost = 2, time = 9, cost = 1100, prestige = 28, happiness = 5, description = "Stegno z dragulji za kralje." },
    royal_imperial_throne = { name = "Kraljevsko cesarsko stegno", woodCost = 5, goldCost = 4, silverCost = 3, jewelCost = 4, pearlCost = 2, silkCost = 2, time = 14, cost = 3000, prestige = 80, happiness = 15, description = "Veliki cesarski prestol z zlatom, dragulji, biseri in svilo za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Stegnarska delavnica", cost = { gold = 350, wood = 200 }, upkeep = 10, qualityBonus = 5 },
    carving_atelier = { name = "Rezbarski atelje", cost = { gold = 1200, wood = 350, stone = 200, gold = 10 }, upkeep = 30, qualityBonus = 20 },
    gilding_chamber = { name = "Pozlatna soba", cost = { gold = 2500, wood = 400, stone = 500, gold = 60, silver = 30 }, upkeep = 60, qualityBonus = 35 },
    royal_throne_atelier = { name = "Kraljevski atelje stegen", cost = { gold = 10000, wood = 800, stone = 1000, gold = 200, jewel = 40 }, upkeep = 200, qualityBonus = 65, prestigeBonus = 50 },
}
ThroneMaker.woodStock = 22; ThroneMaker.stoneStock = 18; ThroneMaker.goldStock = 8; ThroneMaker.silverStock = 6; ThroneMaker.jewelStock = 6; ThroneMaker.pearlStock = 4; ThroneMaker.silkStock = 6
ThroneMaker.productStock = {}; ThroneMaker.buildings = {}; ThroneMaker.maker = nil; ThroneMaker.activeMaking = {}; ThroneMaker.totalProducts = 0; ThroneMaker.dayTimer = 0
function ThroneMaker.init() ThroneMaker.woodStock=22; ThroneMaker.stoneStock=18; ThroneMaker.goldStock=8; ThroneMaker.silverStock=6; ThroneMaker.jewelStock=6; ThroneMaker.pearlStock=4; ThroneMaker.silkStock=6; ThroneMaker.productStock={}; ThroneMaker.buildings={}; ThroneMaker.maker=nil; ThroneMaker.activeMaking={}; ThroneMaker.totalProducts=0; ThroneMaker.dayTimer=0; print("[ThroneMaker] Royal Throne Maker System initialized (6 products, 4 buildings)") end
function ThroneMaker.hireMaker(n,s) s=s or math.random(55,95); local c=600+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ThroneMaker.maker={name=n or ("Stegnar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stegnar najet: %s (spretnost: %d)",ThroneMaker.maker.name,s),"success") end; return true end
function ThroneMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ThroneMaker.build(id) local ok,e=ThroneMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ThroneMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ThroneMaker.getQualityBonus() local b=0; for _,bd in ipairs(ThroneMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ThroneMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and ThroneMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.stoneCost and ThroneMaker.stoneStock<(d.stoneCost or 0) then return false,"Premalo kamna" end; if d.goldCost and ThroneMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.silverCost and ThroneMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.jewelCost and ThroneMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ThroneMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if d.silkCost and ThroneMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if #ThroneMaker.buildings==0 then return false,"Potrebna delavnica" end; if not ThroneMaker.maker then return false,"Potreben stegnar" end; return true end
function ThroneMaker.make(pt,qty) qty=qty or 1; local ok,e=ThroneMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then ThroneMaker.woodStock=ThroneMaker.woodStock-d.woodCost*qty end; if d.stoneCost then ThroneMaker.stoneStock=ThroneMaker.stoneStock-d.stoneCost*qty end; if d.goldCost then ThroneMaker.goldStock=ThroneMaker.goldStock-d.goldCost*qty end; if d.silverCost then ThroneMaker.silverStock=ThroneMaker.silverStock-d.silverCost*qty end; if d.jewelCost then ThroneMaker.jewelStock=ThroneMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ThroneMaker.pearlStock=ThroneMaker.pearlStock-d.pearlCost*qty end; if d.silkCost then ThroneMaker.silkStock=ThroneMaker.silkStock-d.silkCost*qty end; local t=d.time; if ThroneMaker.maker then t=math.max(1,t-math.floor(ThroneMaker.maker.skill/10)) end; table.insert(ThroneMaker.activeMaking,{id="throne_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ThroneMaker.completeMaking(m) local q=1.0+(ThroneMaker.getQualityBonus()/100); if ThroneMaker.maker then q=q+(ThroneMaker.maker.skill/150) end; q=math.min(2.5,q); ThroneMaker.productStock[m.productType]=(ThroneMaker.productStock[m.productType] or 0)+m.quantity; ThroneMaker.totalProducts=ThroneMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ThroneMaker.maker then ThroneMaker.maker.itemsMade=ThroneMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ThroneMaker.maker.skill=math.min(100,ThroneMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stegno izdelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"throne.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ThroneMaker.update(dt) if not _G.state then return end; ThroneMaker.dayTimer=ThroneMaker.dayTimer+dt; if ThroneMaker.dayTimer>=30 then ThroneMaker.dayTimer=0; for i=#ThroneMaker.activeMaking,1,-1 do local m=ThroneMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ThroneMaker.completeMaking(m); table.remove(ThroneMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ThroneMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ThroneMaker.maker then tu=tu+20 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ThroneMaker.getStats() return {woodStock=ThroneMaker.woodStock,stoneStock=ThroneMaker.stoneStock,goldStock=ThroneMaker.goldStock,silverStock=ThroneMaker.silverStock,jewelStock=ThroneMaker.jewelStock,pearlStock=ThroneMaker.pearlStock,silkStock=ThroneMaker.silkStock,productStock=ThroneMaker.productStock,numBuildings=#ThroneMaker.buildings,hasMaker=ThroneMaker.maker~=nil,makerName=ThroneMaker.maker and ThroneMaker.maker.name or "—",makerSkill=ThroneMaker.maker and ThroneMaker.maker.skill or 0,activeMaking=#ThroneMaker.activeMaking,totalProducts=ThroneMaker.totalProducts} end
return ThroneMaker
